// NOTE: The following customization is intentionally retained for backward compatibility.
namespace Azure.ResourceManager.AppService
{
    [CodeGenSerialization(nameof(KeyVaultId), DeserializationValueHook = nameof(DeserializeKeyVaultId))]
    [CodeGenSerialization(nameof(ThumbprintString), DeserializationValueHook = nameof(DeserializeThumbprintString))]
    [CodeGenSuppress("PfxBlob")]
    [CodeGenSuppress("CerBlob")]
    public partial class AppCertificateData
    {
        // GA shipped byte[] for PfxBlob; TypeSpec `bytes` now emits as BinaryData.
        // Restore byte[] for backward compatibility by converting on access.
        /// <summary> Pfx blob. </summary>
        [WirePath("properties.pfxBlob")]
        public byte[] PfxBlob
        {
            get => Properties is null ? null : Properties.PfxBlob?.ToArray();
            set
            {
                if (Properties is null)
                {
                    Properties = new CertificateProperties();
                }
                Properties.PfxBlob = value is null ? null : BinaryData.FromBytes(value);
            }
        }

        // GA shipped byte[] for CerBlob; TypeSpec `bytes` now emits as BinaryData
        // (after restoring Create/Update visibility via @@visibility in client.tsp).
        /// <summary> Raw bytes of .cer file. </summary>
        [WirePath("properties.cerBlob")]
        public byte[] CerBlob
        {
            get => Properties is null ? null : Properties.CerBlob?.ToArray();
            set
            {
                if (Properties is null)
                {
                    Properties = new CertificateProperties();
                }
                Properties.CerBlob = value is null ? null : BinaryData.FromBytes(value);
            }
        }

        /// <summary>
        /// Certificate thumbprint.
        /// <para>
        /// To assign an object to this property use <see cref="BinaryData.FromObjectAsJson{T}(T, System.Text.Json.JsonSerializerOptions?)"/>.
        /// </para>
        /// <para>
        /// To assign an already formated json string to this property use <see cref="BinaryData.FromString(string)"/>.
        /// </para>
        /// <para>
        /// Examples:
        /// <list type="bullet">
        /// <item>
        /// <term>BinaryData.FromObjectAsJson("foo")</term>
        /// <description>Creates a payload of "foo".</description>
        /// </item>
        /// <item>
        /// <term>BinaryData.FromString("\"foo\"")</term>
        /// <description>Creates a payload of "foo".</description>
        /// </item>
        /// <item>
        /// <term>BinaryData.FromObjectAsJson(new { key = "value" })</term>
        /// <description>Creates a payload of { "key": "value" }.</description>
        /// </item>
        /// <item>
        /// <term>BinaryData.FromString("{\"key\": \"value\"}")</term>
        /// <description>Creates a payload of { "key": "value" }.</description>
        /// </item>
        /// </list>
        /// </para>
        /// </summary>
        [EditorBrowsable(EditorBrowsableState.Never)]
        [Obsolete("This property is obsolete and will be removed in a future release. Please use `ThumbprintString` instead.", false)]
        public BinaryData Thumbprint => BinaryData.FromString(ThumbprintString);

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void DeserializeKeyVaultId(JsonProperty property, ref ResourceIdentifier keyVaultId)
        {
            if (property.Value.ValueKind == JsonValueKind.Null || property.Value.GetString().Length == 0)
            {
                return;
            }
            keyVaultId = new ResourceIdentifier(property.Value.GetString());
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void DeserializeThumbprintString(JsonProperty property, ref string thumbprintString)
        {
            if (property.Value.ValueKind == JsonValueKind.Null || property.Value.GetString().Length == 0)
            {
                return;
            }
            thumbprintString = property.Value.GetString();
        }

        /// <summary> Certificate password. </summary>
        [WirePath("properties.password")]
        public string Password { get; set; }    // This property is settable.
    }
}

